-- All fixture rows AND temporary posting enablement are rolled back.
-- Run as the trusted database operator, never through the application.
begin;
do $$
declare b uuid; ar uuid; income uuid; bank uuid; jid uuid; pid uuid; rid uuid; r2 uuid; bad uuid;
 ls jsonb; pay jsonb; tests jsonb:='[]'::jsonb; src text; before_digest jsonb; after_digest jsonb; amount numeric;
begin
 select id,wave_business_id into strict b,src from clickbooks_us.books where code='KTC_US';
 before_digest:=clickbooks_us.audit_source()->'source_digests';
 if (select posting_enabled from clickbooks_us.books where id=b) then raise exception 'QA_REQUIRES_DISABLED_POSTING'; end if;
 insert into clickbooks_us.accounts(book_id,code,name,account_type,normal_side,origin) values(b,'QA-AR','QA receivable','asset','debit','manual') returning id into ar;
 insert into clickbooks_us.accounts(book_id,code,name,account_type,normal_side,origin) values(b,'QA-SALES','QA sales','income','credit','manual') returning id into income;
 insert into clickbooks_us.accounts(book_id,code,name,account_type,normal_side,is_bank_sensitive,origin) values(b,'QA-BANK','QA bank','asset','debit',true,'manual') returning id into bank;
 ls:=jsonb_build_array(jsonb_build_object('account_id',ar,'debit_cents','10000','credit_cents','0'),jsonb_build_object('account_id',income,'debit_cents','0','credit_cents','10000'));
 begin perform clickbooks_us.post_journal(b,'2026-01-02','QA','manual','qa-disabled',ls); raise exception 'QA_EXPECTED_REJECTION'; exception when others then if SQLERRM not like 'CB_POSTING_DISABLED%' then raise; end if; end;
 tests:=tests||'"posting disabled by default"'::jsonb;
 update clickbooks_us.books set posting_enabled=true where id=b;
 jid:=clickbooks_us.post_journal(b,'2026-01-02','QA invoice','manual','qa-invoice',ls);
 if (select status from clickbooks_us.journals where id=jid)<>'posted' then raise exception 'QA_NOT_POSTED'; end if;
 tests:=tests||'"balanced atomic posting"'::jsonb;
 if clickbooks_us.post_journal(b,'2026-01-02','QA invoice','manual','qa-invoice',ls)<>jid then raise exception 'QA_REPLAY_CHANGED'; end if;
 tests:=tests||'"idempotent retry returns original journal"'::jsonb;
 begin perform clickbooks_us.post_journal(b,'2026-01-02','changed','manual','qa-invoice',ls); raise exception 'QA_EXPECTED_REJECTION'; exception when others then if SQLERRM not like 'CB_IDEMPOTENCY_CONFLICT%' then raise; end if; end;
 tests:=tests||'"conflicting duplicate rejected"'::jsonb;
 begin perform clickbooks_us.post_journal(b,'2026-01-02','QA','manual','qa-unbalanced',jsonb_set(ls,'{1,credit_cents}','"9999"')); raise exception 'QA_EXPECTED_REJECTION'; exception when others then if SQLERRM not like 'CB_UNBALANCED%' then raise; end if; end;
 if exists(select 1 from clickbooks_us.journals where source_id='qa-unbalanced') then raise exception 'QA_PARTIAL_JOURNAL'; end if;
 tests:=tests||'"unbalanced journal rejected without partial rows"'::jsonb;
 begin perform clickbooks_us.post_journal(b,'2026-01-02','QA','manual','qa-fraction',jsonb_set(ls,'{0,debit_cents}','"1.5"')); raise exception 'QA_EXPECTED_REJECTION'; exception when others then if SQLERRM not like 'CB_INTEGER_CENTS_REQUIRED%' then raise; end if; end;
 tests:=tests||'"fractional cents rejected"'::jsonb;
 begin perform clickbooks_us.post_journal(b,'2026-01-02','QA','manual','qa-negative',jsonb_set(ls,'{0,debit_cents}','"-1"')); raise exception 'QA_EXPECTED_REJECTION'; exception when others then if SQLERRM not like 'CB_INTEGER_CENTS_REQUIRED%' then raise; end if; end;
 tests:=tests||'"negative amounts rejected"'::jsonb;
 begin perform clickbooks_us.post_journal(b,'2026-01-02','QA','manual','qa-both',jsonb_set(ls,'{0,credit_cents}','"100"')); raise exception 'QA_EXPECTED_REJECTION'; exception when check_violation then null; end;
 tests:=tests||'"debit and credit on same line rejected"'::jsonb;
 begin perform clickbooks_us.post_journal(b,'2026-01-02','QA','manual','qa-zero',jsonb_set(ls,'{0,debit_cents}','"0"')); raise exception 'QA_EXPECTED_REJECTION'; exception when check_violation then null; end;
 tests:=tests||'"zero-value line rejected"'::jsonb;
 begin perform clickbooks_us.post_journal(b,'2026-01-02','QA','manual','qa-one',jsonb_build_array(ls->0)); raise exception 'QA_EXPECTED_REJECTION'; exception when others then if SQLERRM not like 'CB_INVALID_LINE_COUNT%' then raise; end if; end;
 tests:=tests||'"single-line entry rejected"'::jsonb;
 begin perform clickbooks_us.post_journal(b,'infinity','QA','manual','qa-date',ls); raise exception 'QA_EXPECTED_REJECTION'; exception when others then if SQLERRM not like 'CB_INVALID_DATE%' then raise; end if; end;
 tests:=tests||'"invalid date rejected"'::jsonb;
 begin perform clickbooks_us.post_journal(b,'2026-01-02','QA','treasury','qa-wrong-source',ls); raise exception 'QA_EXPECTED_REJECTION'; exception when others then if SQLERRM not like 'CB_INVALID_SOURCE%' then raise; end if; end;
 tests:=tests||'"excluded source type rejected"'::jsonb;
 select id into strict bad from public.accounting_invoices where wave_business_id=src and currency is distinct from 'USD' limit 1;
 begin perform clickbooks_us.post_journal(b,'2026-01-02','QA','accounting_invoice',bad::text,ls); raise exception 'QA_EXPECTED_REJECTION'; exception when others then if SQLERRM not like 'CB_SOURCE_OUT_OF_SCOPE_OR_NOT_POSTABLE%' then raise; end if; end;
 tests:=tests||'"non-USD source invoice rejected"'::jsonb;
 select id into strict bad from public.bank_transactions where wave_business_id=src and pending is true limit 1;
 begin perform clickbooks_us.post_journal(b,'2026-01-02','QA','bank_transaction',bad::text,ls); raise exception 'QA_EXPECTED_REJECTION'; exception when others then if SQLERRM not like 'CB_SOURCE_OUT_OF_SCOPE_OR_NOT_POSTABLE%' then raise; end if; end;
 tests:=tests||'"pending bank source rejected"'::jsonb;
 begin perform clickbooks_us.post_journal(b,'2026-01-02','QA','accounting_invoice',gen_random_uuid()::text,ls); raise exception 'QA_EXPECTED_REJECTION'; exception when others then if SQLERRM not like 'CB_SOURCE_OUT_OF_SCOPE_OR_NOT_POSTABLE%' then raise; end if; end;
 tests:=tests||'"unknown or wrong-silo source rejected"'::jsonb;
 begin update clickbooks_us.journals set description='tamper' where id=jid; raise exception 'QA_EXPECTED_REJECTION'; exception when others then if SQLERRM not like 'CB_IMMUTABLE%' then raise; end if; end;
 tests:=tests||'"posted journal immutable"'::jsonb;
 begin update clickbooks_us.journal_lines set debit_cents=123 where journal_id=jid and line_no=1; raise exception 'QA_EXPECTED_REJECTION'; exception when others then if SQLERRM not like 'CB_IMMUTABLE%' then raise; end if; end;
 tests:=tests||'"posted journal lines immutable"'::jsonb;
 begin delete from clickbooks_us.journals where id=jid; raise exception 'QA_EXPECTED_REJECTION'; exception when others then if SQLERRM not like 'CB_IMMUTABLE%' then raise; end if; end;
 tests:=tests||'"posted journal deletion rejected"'::jsonb;
 begin insert into clickbooks_us.journal_lines(journal_id,book_id,line_no,account_id,debit_cents) values(jid,b,3,ar,1); raise exception 'QA_EXPECTED_REJECTION'; exception when others then if SQLERRM not like 'CB_IMMUTABLE%' then raise; end if; end;
 tests:=tests||'"appending to posted journal rejected"'::jsonb;
 begin update clickbooks_us.accounts set account_type='expense' where id=ar; raise exception 'QA_EXPECTED_REJECTION'; exception when others then if SQLERRM not like 'CB_ACCOUNT_HAS_POSTINGS%' then raise; end if; end;
 tests:=tests||'"posted account reclassification blocked"'::jsonb;
 begin update clickbooks_us.audit_events set event='reversal_posted' where journal_id=jid; raise exception 'QA_EXPECTED_REJECTION'; exception when others then if SQLERRM not like 'CB_APPEND_ONLY%' then raise; end if; end;
 tests:=tests||'"posting audit append-only"'::jsonb;
 pay:=jsonb_build_array(jsonb_build_object('account_id',bank,'debit_cents','10000','credit_cents','0'),jsonb_build_object('account_id',ar,'debit_cents','0','credit_cents','10000'));
 pid:=clickbooks_us.post_journal(b,'2026-01-03','QA payment','manual','qa-payment',pay);
 select net_debit_cents into amount from clickbooks_us.trial_balance(b,'2026-01-03') where account_code='QA-AR';
 if amount<>0 then raise exception 'QA_AR_NOT_CLEARED'; end if;
 select net_debit_cents into amount from clickbooks_us.trial_balance(b,'2026-01-03') where account_code='QA-SALES';
 if amount<>-10000 then raise exception 'QA_REVENUE_DUPLICATED'; end if;
 tests:=tests||'"invoice payment clears receivable without duplicate revenue"'::jsonb;
 select sum(net_debit_cents) into amount from clickbooks_us.trial_balance(b,'2026-01-03');
 if amount<>0 then raise exception 'QA_TRIAL_BALANCE_UNBALANCED'; end if;
 tests:=tests||'"trial balance totals agree"'::jsonb;
 begin perform clickbooks_us.post_journal(b,'2026-01-03','fake reverse','reversal','qa-forged',ls,null,jid); raise exception 'QA_EXPECTED_REJECTION'; exception when others then if SQLERRM not like 'CB_REVERSAL_MISMATCH%' then raise; end if; end;
 tests:=tests||'"incorrect reversal rejected"'::jsonb;
 rid:=clickbooks_us.reverse_journal(pid,'2026-01-04','QA reversal');
 if clickbooks_us.reverse_journal(pid,'2026-01-04','QA reversal')<>rid then raise exception 'QA_REVERSAL_REPLAY_CHANGED'; end if;
 tests:=tests||'"reversal is exact and retry-safe"'::jsonb;
 r2:=clickbooks_us.reverse_journal(jid,'2026-01-04','QA invoice reversal');
 if exists(select 1 from clickbooks_us.trial_balance(b,'2026-01-04') where net_debit_cents<>0) then raise exception 'QA_REVERSAL_NOT_ZERO'; end if;
 tests:=tests||'"original and reversal both retained and net to zero"'::jsonb;
 begin perform clickbooks_us.reverse_journal(r2,'2026-01-05','invalid chain'); raise exception 'QA_EXPECTED_REJECTION'; exception when others then if SQLERRM not like 'CB_INVALID_REVERSAL%' then raise; end if; end;
 tests:=tests||'"reversing a reversal rejected"'::jsonb;
 update clickbooks_us.books set locked_through='2026-01-31' where id=b;
 begin perform clickbooks_us.post_journal(b,'2026-01-31','QA','manual','qa-locked',ls); raise exception 'QA_EXPECTED_REJECTION'; exception when others then if SQLERRM not like 'CB_PERIOD_LOCKED%' then raise; end if; end;
 tests:=tests||'"closed period posting rejected"'::jsonb;
 begin update clickbooks_us.books set wave_business_id='NOT_AN_APPROVED_US_SILO' where id=b; raise exception 'QA_EXPECTED_REJECTION'; exception when others then if SQLERRM not like 'CB_US_BOOK_BINDING_IMMUTABLE%' then raise; end if; end;
 tests:=tests||'"US business binding immutable"'::jsonb;
 if has_schema_privilege('anon','clickbooks_us','USAGE') or has_schema_privilege('authenticated','clickbooks_us','USAGE') then raise exception 'QA_SCHEMA_EXPOSED'; end if;
 if has_table_privilege('service_role','clickbooks_us.journal_lines','INSERT') then raise exception 'QA_SERVICE_CAN_WRITE_LINES'; end if;
 if has_function_privilege('authenticated','public.clickbooks_us_read(boolean)','EXECUTE') or has_function_privilege('anon','public.clickbooks_us_read(boolean)','EXECUTE') then raise exception 'QA_PUBLIC_RPC'; end if;
 tests:=tests||'"anonymous and browser roles denied; no direct service writes"'::jsonb;
 if exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='clickbooks_us' and c.relkind='r' and not c.relrowsecurity) then raise exception 'QA_RLS_MISSING'; end if;
 tests:=tests||'"RLS enabled on every ClickBooks table"'::jsonb;
 if (public.clickbooks_us_read(false)->'trialBalance')<>'null'::jsonb or exists(select 1 from jsonb_array_elements(public.clickbooks_us_read(false)->'accounts') x where (x->>'bankSensitive')::boolean) then raise exception 'QA_BANK_LEAK'; end if;
 tests:=tests||'"bank-disabled response omits sensitive accounts and trial balance"'::jsonb;
 after_digest:=clickbooks_us.audit_source()->'source_digests';
 if before_digest<>after_digest then raise exception 'QA_LEGACY_SOURCE_CHANGED'; end if;
 tests:=tests||'"legacy US source digests unchanged"'::jsonb;
 perform set_config('clickbooks.qa_result',jsonb_build_object('passed',jsonb_array_length(tests),'tests',tests,'fixture_policy','All fixtures and temporary posting enablement rolled back')::text,true);
end $$;
select current_setting('clickbooks.qa_result')::jsonb as qa_result;
rollback;
